-- 1. CREATING THE DATABASE TABLES
DROP TABLE IF EXISTS investigator_dashboard;
DROP TABLE IF EXISTS police_reports;
DROP TABLE IF EXISTS personal_diaries;
DROP TABLE IF EXISTS comms_network;
DROP TABLE IF EXISTS door_access_logs;
DROP TABLE IF EXISTS shuttle_manifest;
DROP TABLE IF EXISTS shuttles;
DROP TABLE IF EXISTS station_doors;
DROP TABLE IF EXISTS environmental_telemetry;
DROP TABLE IF EXISTS crew;

CREATE TABLE crew (
    crew_id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    role TEXT NOT NULL,
    department TEXT NOT NULL,
    manager_id INTEGER,
    salary INTEGER
);

CREATE TABLE investigator_dashboard (
    case_id INTEGER PRIMARY KEY,
    title TEXT NOT NULL,
    assigned_to TEXT NOT NULL,
    status TEXT NOT NULL,
    urgency INTEGER NOT NULL,
    content TEXT NOT NULL,
    created_at TIMESTAMP
);

CREATE TABLE police_reports (
    report_id INTEGER PRIMARY KEY,
    officer_id INTEGER NOT NULL,
    subject TEXT NOT NULL,
    transcript TEXT NOT NULL,
    created_at TIMESTAMP,
    FOREIGN KEY(officer_id) REFERENCES crew(crew_id)
);

CREATE TABLE personal_diaries (
    diary_id INTEGER PRIMARY KEY,
    owner_id INTEGER NOT NULL,
    password_hint TEXT NOT NULL,
    entry_text TEXT NOT NULL,
    FOREIGN KEY(owner_id) REFERENCES crew(crew_id)
);

CREATE TABLE comms_network (
    msg_id INTEGER PRIMARY KEY,
    sender_id INTEGER NOT NULL,
    receiver_id INTEGER NOT NULL,
    message TEXT NOT NULL,
    sent_at DATE NOT NULL,
    FOREIGN KEY(sender_id) REFERENCES crew(crew_id),
    FOREIGN KEY(receiver_id) REFERENCES crew(crew_id)
);

CREATE TABLE station_doors (
    door_id TEXT PRIMARY KEY,
    sector_name TEXT NOT NULL,
    description TEXT NOT NULL
);

CREATE TABLE door_access_logs (
    access_id INTEGER PRIMARY KEY,
    crew_id INTEGER NOT NULL,
    door_id TEXT NOT NULL,
    access_time TIMESTAMP NOT NULL,
    status TEXT, 
    FOREIGN KEY(crew_id) REFERENCES crew(crew_id),
    FOREIGN KEY(door_id) REFERENCES station_doors(door_id)
);

CREATE TABLE shuttles (
    shuttle_id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    last_docking_bay TEXT NOT NULL,
    flight_notes TEXT
);

CREATE TABLE shuttle_manifest (
    manifest_id INTEGER PRIMARY KEY,
    shuttle_id INTEGER NOT NULL,
    passenger_id INTEGER, 
    board_time TIMESTAMP NOT NULL,
    FOREIGN KEY(shuttle_id) REFERENCES shuttles(shuttle_id),
    FOREIGN KEY(passenger_id) REFERENCES crew(crew_id)
);

CREATE TABLE environmental_telemetry (
    telemetry_id INTEGER PRIMARY KEY,
    area_name TEXT NOT NULL,
    oxygen_level INTEGER NOT NULL,
    temperature REAL NOT NULL,
    scanned_at TIMESTAMP
);


