INSERT INTO investigator_dashboard VALUES (1, 'Solenoid Valve Leak', 'Tech Rogers', 'Resolved', 1, 'Standard system log: Solenoid Valve Leak in sector 4. Dispatched crew to investigate.', '2084-03-05 12:44:00');
INSERT INTO investigator_dashboard VALUES (2, 'Minor Bar Scuffle', 'Officer Smith', 'Closed', 2, 'Two miners had an argument over rations. Both sent to quarters to cool off.', '2084-03-08 23:15:00');
INSERT INTO investigator_dashboard VALUES (3, 'Reactor Coolant Pressure Anomaly', 'Chief Investigator', 'Active', 5, 'Reactor core pressure fluctuation detected. Primary system stabilized, but alert remains flagged active until full physical inspection.', '2084-03-12 10:00:00');
INSERT INTO investigator_dashboard VALUES (4, 'Unauthorized Lift Request', 'Unassigned', 'Active', 2, 'Lift terminal in Sector 1 registered an unauthorized override card. Scanning lift logs.', '2084-03-11 14:22:00');
INSERT INTO investigator_dashboard VALUES (5, 'Missing Person: Dr. Evelyn Vance (Archived)', 'Chief Investigator', 'Resolved', 2, 'Dr. Vance went missing in Sector 2 storage corridors. Found locked inside a clean room after 3 hours. No foul play detected.', '2084-02-15 09:00:00');
INSERT INTO investigator_dashboard VALUES (6, 'Noise Complaint', 'Officer Smith', 'Resolved', 1, 'Loud music coming from Quarter 4-B. Warning issued.', '2084-03-09 22:10:00');
INSERT INTO investigator_dashboard VALUES (7, 'Power Grid Flicker', 'Tech Rogers', 'Closed', 3, 'Temporary voltage drop in Sector 8 secondary lines. Transformer reset.', '2084-03-12 11:45:00');
INSERT INTO investigator_dashboard VALUES (8, 'Camera Blackout Sector 2', 'Chief Investigator', 'Active', 3, 'Camera feed 24-B went dark. Commencing manual diagnostic scan of fiber lines.', '2084-03-13 06:12:00');
INSERT INTO investigator_dashboard VALUES (9, 'Oxygen Tank Level Drop', 'Tech Rogers', 'Resolved', 4, 'Pressure warning on Tank B-4. Gasket replaced.', '2084-03-06 18:30:00');
INSERT INTO investigator_dashboard VALUES (10, 'Waste Recycler Backflow', 'Chief Investigator', 'Active', 2, 'Recycler unit 9 backup. Flushing lines to clear blockages.', '2084-03-13 06:12:00');
INSERT INTO investigator_dashboard VALUES (11, 'Terminal Injection Attempt', 'Deputy Davis', 'Pending', 4, 'Unknown MAC address attempted to run command scripts on Admin network.', '2084-03-12 17:05:00');
INSERT INTO investigator_dashboard VALUES (12, 'Stolen Ration Pack', 'Officer Smith', 'Closed', 1, 'A protein case was reported missing from Engineering locker room.', '2084-03-04 15:30:00');
INSERT INTO investigator_dashboard VALUES (13, 'Pressure Seal Degradation', 'Chief Investigator', 'Active', 3, 'Airlock door 12-A seal showing micro-fractures under sensor check.', '2084-03-13 06:12:00');
INSERT INTO investigator_dashboard VALUES (14, 'Unscheduled Cargo Shuttle', 'Unassigned', 'Pending', 3, 'A cargo tug dropped off grids briefly before landing in Bay 1.', '2084-03-13 01:00:00');
INSERT INTO investigator_dashboard VALUES (15, 'Suspicious Activity: Dr. Evelyn Vance', 'Deputy Miller', 'Active', 4, 'Dr. Vance was seen entering restricted server archives late at night. Security team is running a routine security scan.', '2084-03-12 14:30:00');
INSERT INTO investigator_dashboard VALUES (16, 'Decommissioned Sector Alert', 'Chief Investigator', 'Active', 2, 'Sensor ping detected in abandoned sector 14. Likely a debris impact.', '2084-03-13 06:12:00');
INSERT INTO investigator_dashboard VALUES (17, 'Docking Arm Lag', 'Tech Rogers', 'Resolved', 2, 'Docking clamp 4 delayed response. Lubricated actuators.', '2084-03-07 11:00:00');
INSERT INTO investigator_dashboard VALUES (18, 'Missing Person: Lab Assistant James', 'Chief Investigator', 'Active', 3, 'Lab assistant James Holloway missed morning roll call. Possibly overslept. Run a standard locator sweep.', '2084-03-13 06:12:00');
INSERT INTO investigator_dashboard VALUES (19, 'Solenoid Valve Leak', 'Tech Rogers', 'Resolved', 1, 'Standard system log: Solenoid Valve Leak in sector 9.', '2084-03-03 14:00:00');
INSERT INTO investigator_dashboard VALUES (20, 'Minor Bar Scuffle', 'Officer Smith', 'Closed', 2, 'Routine scuffle in recreational lounge. No injuries.', '2084-03-05 21:40:00');
INSERT INTO investigator_dashboard VALUES (21, 'Hydroponics Filter Clog', 'Deputy Davis', 'Pending', 1, 'Filter system 2 cleaning required.', '2084-03-08 10:15:00');
INSERT INTO investigator_dashboard VALUES (22, 'Unauthorized Lift Request', 'Chief Investigator', 'Active', 2, 'Tech terminal log bypass attempt in Sector 3. Investigating node source.', '2084-03-13 06:12:00');
INSERT INTO investigator_dashboard VALUES (23, 'Power Grid Flicker', 'Tech Rogers', 'Closed', 3, 'Sub-station fluctuation. Rerouted power pathways.', '2084-03-11 16:50:00');
INSERT INTO investigator_dashboard VALUES (24, 'Camera Blackout Sector 2', 'Chief Investigator', 'Active', 3, 'Circuit breaker trip in Sector 2 monitoring station. Dispatching automated diagnostic probe.', '2084-03-13 06:12:00');
INSERT INTO investigator_dashboard VALUES (25, 'Oxygen Tank Level Drop', 'Tech Rogers', 'Resolved', 4, 'Auxiliary reservoir calibration error fixed.', '2084-03-09 09:12:00');
INSERT INTO investigator_dashboard VALUES (26, 'Water Recycler Calibration Drift', 'Chief Investigator', 'Active', 3, 'Calibration drift in secondary water recycling loop. High salt content flagged in quarters segment B.', '2084-03-13 06:12:00');
INSERT INTO investigator_dashboard VALUES (27, 'Missing Person: Dr. Evelyn Vance', 'Chief Investigator', 'Active', 5, 'Dr. Evelyn Vance (Xenobiology) did not report for her morning shift. Her mother filed a missing person report last night. She spoke to a rookie officer whose name starts with "J". This rookie is supervised by Sergeant Reyes (Manager ID: 45) and has filed exactly 3 reports total. Find this officer''s reports to see what the mother told him.', '2084-03-13 06:12:00');
INSERT INTO investigator_dashboard VALUES (28, 'Terminal Injection Attempt', 'Deputy Davis', 'Pending', 4, 'Brute force login logs from station perimeter node.', '2084-03-11 02:15:00');
