INSERT INTO personal_diaries VALUES (1, 1050, 'default', 'Don''t forget to buy milk.');
INSERT INTO personal_diaries VALUES (2, 1060, 'My favorite movie star wars', 'Draft: I love Star Wars. Han Solo is the coolest pilot ever.');
INSERT INTO personal_diaries VALUES (3, 101, 'default', 'Note to self: Clean the laser pistol before the next range drill.');
INSERT INTO personal_diaries VALUES (4, 45, 'starfish', 'Saw a cool starfish documentary in the rec room today.');
INSERT INTO personal_diaries VALUES (5, 102, 'birthday', 'Drafting an invite list for my 30th birthday on Deck 4.');
INSERT INTO personal_diaries VALUES (6, 103, 'default', 'Paid 50 credits to the mess hall supervisor for extra coffee packets.');
INSERT INTO personal_diaries VALUES (7, 104, 'first_pet', 'Miss my golden retriever back on Earth. Space stations are no place for dogs.');
INSERT INTO personal_diaries VALUES (8, 105, 'favorite_element', 'Hydrogen. Simple, elegant, and keeps the reactor going.');
INSERT INTO personal_diaries VALUES (9, 3056, 'default', 'Remember to backup the local subnet router logs on Friday.');
INSERT INTO personal_diaries VALUES (10, 3058, 'lucky_number', 'Always bet on 7. It hasn''t let me down in the lounge games yet.');
INSERT INTO personal_diaries VALUES (11, 98, 'default', 'Reviewed the new security protocol drafts. Sterling is getting paranoid.');
INSERT INTO personal_diaries VALUES (12, 1008, 'starry night', 'Just a draft of an email to my daughter on Earth. Reminding her to take painting classes.');
INSERT INTO personal_diaries VALUES (13, 10, 'halsey_secure', 'The Director has requested a summary of the bio-capsule telemetry. I don''t trust his motives.');
INSERT INTO personal_diaries VALUES (14, 46, 'default', ' Powell''s log: Quiet shift tonight. Sector 5 had zero incidents.');
INSERT INTO personal_diaries VALUES (15, 99, 'sterling_admin', 'The board is demanding higher yields from the xenobiology lab. I need to push Vance harder.');
INSERT INTO personal_diaries VALUES (16, 1001, 'rocinante', 'Holden''s log: The crew is complaining about the quality of the synthetic tea.');
INSERT INTO personal_diaries VALUES (17, 1002, 'default', 'Nagata''s log: Replaced the water recycler micro-filter. Running at 98% efficiency.');
INSERT INTO personal_diaries VALUES (18, 1003, 'default', 'Burton''s log: Sledgehammer is missing from the engineering locker. Someone''s going to pay.');
INSERT INTO personal_diaries VALUES (19, 1014, 'shooting star', 'Saw a shooting star from the cargo bay viewport. Reminded me of the skies back home.');
INSERT INTO personal_diaries VALUES (20, 1004, 'mcrn_pilot', 'Kamal''s log: Calibrated thruster thruster-pack arrays. Smooth flying ahead.');
INSERT INTO personal_diaries VALUES (21, 1005, 'default', 'Draper''s log: Ran 10 kilometers on the centrifuge treadmill. Feeling strong.');
INSERT INTO personal_diaries VALUES (22, 1006, 'default', 'Mao''s log: Just read a message from my father. Same old corporate nonsense.');
INSERT INTO personal_diaries VALUES (23, 1007, 'hat_hint', 'Miller''s log: Lost my favorite hat near the Sector 9 lift. Need to track it down.');
INSERT INTO personal_diaries VALUES (24, 1009, 'default', 'Okoye''s log: Spore growth in Sector 4 is exceeding models. Very fascinating.');
INSERT INTO personal_diaries VALUES (25, 1010, 'default', 'Avasarala''s log: These administrators think they can outsmart me. They are wrong.');
INSERT INTO personal_diaries VALUES (26, 1011, 'default', 'Errinwright''s log: Security updates look normal. Nothing to report to the Director.');
INSERT INTO personal_diaries VALUES (27, 1042, 'The evening star', 'Aurelia Corp is weaponizing my research. I have to run. I contacted Jaxom (Crew ID: 3055). He said he''d help me escape. He’s going to override a security door in Sector 9 so we can get to a shuttle. He told me: ''Look at the access logs. I will try to bypass the door. Look for a door in Sector 9 where I have more than 4 access attempts, and where at least one status is NULL—that’s where I''ll cut the security feed wires.'' I''m going to meet him there at midnight.');
INSERT INTO personal_diaries VALUES (28, 1012, 'default', 'Mao''s log: Sub-level development is slightly behind schedule. Need more technicians.');
INSERT INTO personal_diaries VALUES (29, 1013, 'default', 'Johnson''s log: Shift roster is unbalanced. Too many rookies in Sector 9.');
INSERT INTO personal_diaries VALUES (30, 1015, 'default', 'Ashford''s log: Evaluated secondary airlock pressure gates. All seals holding.');
INSERT INTO personal_diaries VALUES (31, 1016, 'default', 'Dawes''s log: The workers on Deck 4 are demanding better air quality filtration.');
INSERT INTO personal_diaries VALUES (32, 1017, 'default', 'Ghazi''s log: Completed executive security sweep of the administrator suites.');
INSERT INTO personal_diaries VALUES (33, 1018, 'default', 'Lawson''s log: System databases are fully optimized. Cleared 12GB of cache.');
INSERT INTO personal_diaries VALUES (34, 1019, 'default', 'Strickland''s log: Samples are safely stored in Vault B. Temperature holding.');
INSERT INTO personal_diaries VALUES (35, 1002, 'starlight', 'Nagata''s log: Need to adjust the solar collector angles tomorrow to catch maximum starlight.');
INSERT INTO personal_diaries VALUES (36, 101, 'default', 'Vance''s log: Picked up rookie shift at Sector 9 corridor guard desk.');
INSERT INTO personal_diaries VALUES (37, 102, 'default', 'Doe''s log: Assisted with the routine locker inspections in Sector 1.');
INSERT INTO personal_diaries VALUES (38, 103, 'default', 'Smith''s log: Investigating minor water spill on Deck 2. False alarm.');
INSERT INTO personal_diaries VALUES (39, 104, 'default', 'Ryan''s log: Completed shift handover with Sgt Reyes. No active reports.');
INSERT INTO personal_diaries VALUES (40, 105, 'default', 'Higgins''s log: Checked the emergency escape ladders on Deck 5. Clean.');
INSERT INTO personal_diaries VALUES (41, 3055, 'default', 'Sterling''s log: These cargo bay doors are constantly jamming. Cheap gears.');
INSERT INTO personal_diaries VALUES (42, 3056, 'default', 'Brody''s log: IT ticket 452 resolved. Replaced faulty terminal interface.');
INSERT INTO personal_diaries VALUES (43, 3058, 'default', 'Connor''s log: Patched a micro-breach in secondary cooling line. Done.');
INSERT INTO personal_diaries VALUES (44, 1050, 'star trek', 'Draft: Live long and prosper. Spock is still the best character in sci-fi.');
INSERT INTO personal_diaries VALUES (45, 98, 'default', 'Miller''s log: Checked the weapon lockers in local sub-station. Secure.');
INSERT INTO personal_diaries VALUES (46, 10, 'default', 'Halsey''s log: DNA sequences are confirming the spore mutation rates. Shocking.');
INSERT INTO personal_diaries VALUES (47, 45, 'default', 'Reyes''s log: Rookie training module 4 scheduled for tomorrow morning.');
INSERT INTO personal_diaries VALUES (48, 46, 'default', 'Powell''s log: Re-calibrated hand-scanners at local checkpoints.');
INSERT INTO personal_diaries VALUES (49, 99, 'default', 'Sterling''s log: Secure datapad received from Earth executives.');
INSERT INTO personal_diaries VALUES (50, 1001, 'default', 'Holden''s log: Water reserves are tasting metallic. Filters need checking.');
INSERT INTO personal_diaries VALUES (51, 1003, 'default', 'Burton''s log: The hydraulic lift works smoothly now. Cleaned the pistons.');
INSERT INTO personal_diaries VALUES (52, 1018, 'starburst matrix', 'Encrypted matrix backup log: [45df89-ab992-cf110-aa82]. Just lines of base64.');
INSERT INTO personal_diaries VALUES (53, 1004, 'default', 'Kamal''s log: Fuel tank 3 pressure is holding fine under simulation.');
INSERT INTO personal_diaries VALUES (54, 1005, 'default', 'Draper''s log: Completed heavy armor inventory check. All gear accounted for.');
INSERT INTO personal_diaries VALUES (55, 1006, 'default', 'Mao''s log: Standard routine shifts are getting boring. Need a real assignment.');
