INSERT INTO shuttles VALUES (1, 'The Horizon', 'Bay 3', 'Routine mineral cargo run to lunar base. Fuel cells at 92%.');
INSERT INTO shuttles VALUES (2, 'Nova', 'Bay 2', 'Maintenance shuttle. Undergoing thruster alignment in lower bay.');
INSERT INTO shuttles VALUES (3, 'Serenity', 'Bay 1', 'Transported agricultural staff from Hydroponics Deck. All clear.');
INSERT INTO shuttles VALUES (4, 'Rocinante', 'Bay 4', 'Security patrol vessel. Standard weapon lock system engaged.');
INSERT INTO shuttles VALUES (5, 'Canterbury', 'Bay 3', 'Water hauling freighter. Ice haul from Saturn ring orbit logged.');
INSERT INTO shuttles VALUES (6, 'Razorback', 'Bay 5', 'High-speed racing pinnace. Private registration. Clearance verified.');
INSERT INTO shuttles VALUES (7, 'Canis Major', 'Bay 3', 'Heavy mining barge. Cargo containing raw iron ore scheduled for melt.');
INSERT INTO shuttles VALUES (8, 'Geryon', 'Bay 2', 'Waste extraction shuttle. Tank levels at 45%. Maintenance required.');
INSERT INTO shuttles VALUES (9, 'Sovereign', 'Bay 1', 'Executive shuttle. Reserved for Director Sterling''s personal travel.');
INSERT INTO shuttles VALUES (10, 'Defiant', 'Bay 4', 'Tactical defense ship. Undergoing target scanner diagnostic.');
INSERT INTO shuttles VALUES (11, 'Voyager', 'Bay 2', 'Deep space probe handler. Offloaded drone telemetry to main server.');
INSERT INTO shuttles VALUES (12, 'Enterprise', 'Bay 3', 'Science division runner. Transported replacement soil filters.');
INSERT INTO shuttles VALUES (13, 'Discovery', 'Bay 5', 'Research vessel. Prepped for long-range spatial anomaly scanning.');
INSERT INTO shuttles VALUES (14, 'Prometheus', 'Bay 1', 'Experimental reactor tender. Authorized personnel only.');
INSERT INTO shuttles VALUES (15, 'Daedalus', 'Bay 3', 'Engineering heavy lifter. Scheduled to replace solar array panel 4.');
INSERT INTO shuttles VALUES (16, 'Odyssey', 'Bay 4', 'Personnel transport shuttle. Brought 15 new security recruits.');
INSERT INTO shuttles VALUES (17, 'Covenant', 'Bay 2', 'Colonist transport framework. Cargo hold empty. Cleaning in progress.');
INSERT INTO shuttles VALUES (18, 'Nautilus', 'Bay 3', 'Sub-surface ice explorer. Secured in dry dock for hull inspection.');
INSERT INTO shuttles VALUES (19, 'Pegasus', 'Bay 1', 'Operations courier. Delivered medical supplies to Infirmary.');
INSERT INTO shuttles VALUES (20, 'Hyperion', 'Bay 5', 'Heavy freighter. Unloaded 40 tons of processed nutrient blocks.');
INSERT INTO shuttles VALUES (21, 'Tardigrade', 'Bay 3', 'Xenobiology research runner. Disinfected after bio-spore run.');
INSERT INTO shuttles VALUES (22, 'Chronos', 'Bay 4', 'Time-dilation test shuttle. Automated telemetry run logged.');
INSERT INTO shuttles VALUES (23, 'Atlas', 'Bay 2', 'Structural repair shuttle. Welders dispatched to Sector 8 bulkhead.');
INSERT INTO shuttles VALUES (24, 'Titan', 'Bay 1', 'Mining escort vessel. Undergoing engine burn tests.');
INSERT INTO shuttles VALUES (25, 'The Nomad', 'Bay 3', 'Suspicious registration. Logged minor fuel theft from primary tanks. No crew currently onboard.');
INSERT INTO shuttles VALUES (26, 'The Drifter', 'Bay 2', 'Contractor shuttle. Used by welding crew for exterior maintenance.');
INSERT INTO shuttles VALUES (27, 'The Wanderer', 'Bay 3', 'Docking successful in decommissioned zone. Primary power offline to avoid radar. Environmental systems active but running on emergency batteries. If you are reading this, Evelyn, we are hiding in one of the decommissioned sectors. To find which one, search the live telemetry logs for active oxygen levels (> 0) in areas marked ''Decommissioned''. To save power, we chose the sector with the 2nd lowest temperature.');
INSERT INTO shuttles VALUES (28, 'The Ghost', 'Bay 4', 'Decommissioned hull. Stripped of engines and core navigation relays.');
INSERT INTO shuttles VALUES (29, 'Vanguard', 'Bay 3', 'Security interceptor. Prepped for launch in case of station lockdown.');
INSERT INTO shuttles VALUES (30, 'Galactica', 'Bay 5', 'Heavy transport. Cargo hold containing spare steel structural beams.');
INSERT INTO shuttles VALUES (31, 'Icarus', 'Bay 1', 'Solar radiation research vessel. Thermal shielding showing 12% wear.');
INSERT INTO shuttles VALUES (32, 'Endeavour', 'Bay 2', 'Routine shuttle run from Lunar orbital post. Passenger roster logged.');
INSERT INTO shuttles VALUES (33, 'Challenger', 'Bay 3', 'Military liaison shuttle. Cleared for flight path to high orbit.');
INSERT INTO shuttles VALUES (34, 'Columbia', 'Bay 4', 'Cargo barge. Offloaded standard freeze-dried agricultural products.');
INSERT INTO shuttles VALUES (35, 'Atlantis', 'Bay 5', 'Scientific survey ship. Recovered deep space soil samples.');
INSERT INTO shuttles VALUES (36, 'Goliath', 'Bay 1', 'Heavy tug. Assisted damaged mineral barge into docking ring 2.');
INSERT INTO shuttles VALUES (37, 'Behemoth', 'Bay 3', 'Massive cargo vessel. Locked down for scheduled customs sweep.');
INSERT INTO shuttles VALUES (38, 'Phoenix', 'Bay 2', 'Reconstructed scrap shuttle. Maintenance clearance pending.');
INSERT INTO shuttles VALUES (39, 'Siren', 'Bay 4', 'Communications relay tender. Replaced transmitter modules on buoy.');
INSERT INTO shuttles VALUES (40, 'Apex', 'Bay 1', 'High-priority transport. Delivered sensitive corporate secure datapad.');
INSERT INTO shuttles VALUES (41, 'Nebula', 'Bay 3', 'Astronomical mapping runner. Processing telescope alignment data.');
INSERT INTO shuttles VALUES (42, 'Solaris', 'Bay 5', 'Solar array cleaner shuttle. Automated operations logged.');
INSERT INTO shuttles VALUES (43, 'Specter', 'Bay 2', 'Unidentified scout ship. Impounded by Security pending registration verification.');
INSERT INTO shuttles VALUES (44, 'Aurora', 'Bay 4', 'Personnel commuter. Shift rotation staff returned to civilian sector.');
INSERT INTO shuttles VALUES (45, 'The Seeker', 'Bay 3', 'Private exploration craft. Docked for fuel cell replacement. Notes indicate ship is empty.');
INSERT INTO shuttles VALUES (46, 'Stardust', 'Bay 1', 'Hydroponics organic soil deliverer. Tank levels cleared.');
INSERT INTO shuttles VALUES (47, 'Eclipse', 'Bay 5', 'Solar array repair shuttle. Scheduled for tomorrow morning shift.');
INSERT INTO shuttles VALUES (48, 'Zenith', 'Bay 3', 'High-altitude research run to gas giant atmosphere. Processing samples.');
INSERT INTO shuttles VALUES (49, 'Vector', 'Bay 2', 'Navigational beacon calibration shuttle. Flight files updated.');
INSERT INTO shuttles VALUES (50, 'Equinox', 'Bay 4', 'Standard shuttle. Undergoing standard structural pressure checks.');
INSERT INTO shuttles VALUES (51, 'Halcyon', 'Bay 1', 'Medical evacuation shuttle. Empty. Standard supplies stocked.');
INSERT INTO shuttles VALUES (52, 'Valiant', 'Bay 3', 'Security support vessel. Shift standby rotation complete.');
INSERT INTO shuttles VALUES (53, 'Excalibur', 'Bay 5', 'VIP transport runner. Cleaned and prepped for flight path.');
INSERT INTO shuttles VALUES (54, 'Zephyr', 'Bay 2', 'Operations liaison craft. Flight notes show typical corridor run.');
INSERT INTO shuttles VALUES (55, 'Infinity', 'Bay 4', 'Heavy mineral freighter. Engine core heating cycle diagnostic active.');
